function analyze(release) {
  let sumX = 0, sumY = 0, totalChroma = 0;
  for (const swatch of release.palette) {
    const w = swatch.chroma * swatch.fraction;   // weight
    const θ = swatch.hue * Math.PI / 180;
    sumX += Math.cos(θ) * w;                     // polar → cartesian
    sumY += Math.sin(θ) * w;                     // (chroma-weighted)
    totalChroma += swatch.chroma * swatch.fraction;
  }
  const hue    = Math.atan2(sumY, sumX) * 180 / Math.PI;
  const chroma = totalChroma;
  return { hue, chroma };                        // → polar dot
}
